import {createCredentialUI} from './credentials-ui.js';
import {describeChange} from './language.js';
import {upgradeState,activeCase,activeMeasurements,day} from './lifecycle.js';
import {createDailyHistory} from './history.js';
import {createLifecycleUI} from './lifecycle-ui.js';
import {AREAS,SITES,PROFILES,medical,clinician,today,makeSeed,stamp,audit,scan,addMeasurement,acknowledge,addAction,reconcile,syncSite,snapshot} from './core.js';
const KEY='dmf-pob-health-demo-v1';
let data;try{const raw=localStorage.getItem(KEY);data=raw?JSON.parse(raw):makeSeed();if(data.schema!==1||!Array.isArray(data.people))throw Error();}catch{data=makeSeed();}
data=upgradeState(data);
const ui={accountId:'admin',reportFrom:'2026-10-01',reportTo:today,page:'overview',site:'all',role:'admin',area:'all',search:'',category:'all',presence:'inside',pageNo:1,clinicStatus:'active',dcuStatus:'all',dcuPage:1,menuOpen:false};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=t=>t?new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(t)):'—';
const actor=()=>data.accounts.find(a=>a.id===ui.accountId)?.name||PROFILES[ui.role].name;
const auditDetail=a=>medical(ui.role)||!/medis|DCU|dokter/i.test(a.action)?describeChange(a.detail):'Detail medis dibatasi';
const inReportRange=t=>(!ui.reportFrom||day(t)>=ui.reportFrom)&&(!ui.reportTo||day(t)<=ui.reportTo);
const person=id=>data.people.find(p=>p.id===id);
const latest=id=>activeMeasurements(data).find(m=>m.personId===id);
const inSite=x=>ui.site==='all'||x.site===ui.site;
const caseMeasure=c=>data.measurements.find(m=>m.id===c.measurementId);
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',report:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8ZM14 2v6h6M8 13h8M8 17h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M13 6l6 6-6 6',scan:'M7 3H3v4M17 3h4v4M3 17v4h4M21 17v4h-4M7 8v8M11 8v8M15 8v8M18 8v8',plus:'M12 5v14M5 12h14',download:'M12 3v12M7 10l5 5 5-5M5 16v5h14v-5',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6ZM8 12l3 3 5-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M4 12l5 5L20 6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.home}"/></svg>`;
const pill=(label,type='')=>`<span class="pill ${type}">${E(({'Tidak memerlukan tindak lanjut':'Sesuai batas','Perlu pemeriksaan klinik':'Perlu ke klinik','Data belum lengkap':'Belum lengkap','Ditangani':'Dalam pemeriksaan'})[label]||label)}</span>`;
const init=name=>name.split(' ').slice(0,2).map(s=>s[0]).join('');
const nameCell=p=>`<div class="person"><span class="avatar">${E(init(p.name))}</span><div><button class="link" data-action="person" data-id="${E(p.id)}">${E(p.name)}</button><div class="muted">${E(p.id)} · ${E(p.category)}</div></div></div>`;
const noData=(cols,text='Belum ada data sesuai pilihan.')=>`<tr><td colspan="${cols}" class="empty">${E(text)}</td></tr>`;
const btn=(text,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${cls.includes('test-trigger')?'title="Fitur simulasi untuk pengujian; tidak digunakan saat perangkat sudah terpasang"':''} ${attrs}>${text}${cls.includes('test-trigger')?'<span class="test-badge">SIMULASI</span>':''}</button>`;
const siteOptions=(all=true,sel=ui.site)=>(all?`<option value="all" ${sel==='all'?'selected':''}>Kedua CPP</option>`:'')+SITES.map(x=>`<option ${sel===x?'selected':''}>${x}</option>`).join('');
const areaOptions=(scope=true,selected='SITE')=>(scope?'<option value="SITE">Gerbang kawasan / pos security</option>':'<option value="">Di antara area</option>')+AREAS.map(a=>`<option value="${E(a)}" ${selected===a?'selected':''}>${E(a)}</option>`).join('');
function save(){data=upgradeState(data);try{localStorage.setItem(KEY,JSON.stringify(data));}catch{toast('Penyimpanan browser gagal. Unduh cadangan data sebelum menutup halaman.',true);}}
let toastTimer;function toast(text,error=false){const t=document.querySelector('#toast');t.textContent=text;t.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',5000);}
function head(eyebrow,title,desc,actions=''){const titles={overview:'Ringkasan',pob:'Keberadaan personel',dcu:'Pemeriksaan kesehatan',clinic:'Klinik',history:'Riwayat harian',reports:'Laporan',admin:'Administrasi',settings:'Pengaturan'};return `<div class="page-head"><h1>${titles[ui.page]||title}</h1><div class="actions">${actions}</div></div>`;}
function stat(label,value,context,ic='people',alert=false){
 const historyLabels=['Catatan masuk','Catatan keluar','Orang diperiksa','Kegiatan klinik','Orang tercatat','Perlu diperiksa petugas'];
 const adminLabels=['Aktif','Nonaktif','Arsip','Total identitas'];
 const clickable=['Catatan perlu diperiksa','Belum diperiksa','Klinik menunggu','Orang di dalam kawasan','Personel terdaftar','Sudah DCU hari ini','Perlu tindak lanjut','Tercatat di dalam','Internal','Mitra kerja','Tamu','Sudah diperiksa','Belum DCU di dalam CPP','Hasil perlu tindak lanjut','Hasil belum lengkap','Alarm baru','Dalam pemeriksaan','Kasus selesai','Total kasus',...historyLabels,...adminLabels].includes(label);
 const action=historyLabels.includes(label)?'history-summary':adminLabels.includes(label)?'lc-stat':'summary';
 const active=ui.page==='pob'&&ui.presence==='inside'&&ui.area==='all'&&!ui.search&&(label==='Tercatat di dalam'?ui.category==='all':ui.category===label)||ui.page==='clinic'&&({new:'Alarm baru',ongoing:'Dalam pemeriksaan',closed:'Kasus selesai',all:'Total kasus'}[ui.clinicStatus]===label)||ui.page==='dcu'&&({all:'Sudah diperiksa','needs-review':'Hasil perlu tindak lanjut',incomplete:'Hasil belum lengkap'}[ui.dcuStatus]===label);
 const display=({'Orang di dalam kawasan':'Di dalam kawasan','Tercatat di dalam':'Di dalam kawasan','Belum DCU di dalam CPP':'Belum diperiksa','Hasil perlu tindak lanjut':'Perlu ke klinik','Hasil belum lengkap':'Belum lengkap','Klinik menunggu':'Kasus klinik aktif','Catatan perlu diperiksa':'Perlu verifikasi'})[label]||label;
 const body=`<span class="label">${display}</span><span class="stat-icon">${icon(ic)}</span><strong>${value}</strong>${clickable?'<span class="stat-chevron" aria-hidden="true">›</span>':''}`;
 return clickable?`<button type="button" class="stat stat-button ${alert?'alert':''} ${active?'selected':''}" data-action="${action}" data-label="${E(label)}" aria-label="${E(display)}: ${value}">${body}</button>`:`<div class="stat ${alert?'alert':''}">${body}</div>`;
}
function render(){
 const active=data.cases.filter(c=>activeCase(c)&&inSite(c));const nav=[['overview','Ringkasan','home'],['pob','Keberadaan personel','people'],...(medical(ui.role)?[['dcu','Pemeriksaan harian','heart'],['clinic','Klinik','bell']]:[]),['history','Riwayat harian','clock'],['reports','Laporan','report'],...(ui.role==='admin'?[['admin','Administrasi','shield']]:[]),['settings','Pengaturan','settings']];
 document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar ${ui.menuOpen?'menu-open':''}"><div class="brand"><span class="brandmark">POB</span><div><strong>Donggi Matindok</strong><small>PERSONEL DAN KESEHATAN</small></div><button class="mobile-menu-toggle" data-action="mobile-menu" aria-controls="main-navigation" aria-expanded="${ui.menuOpen}"><span aria-hidden="true">☰</span> Menu</button></div><div><div class="navlabel">Ruang kerja</div><nav class="nav" id="main-navigation" aria-label="Menu utama">${nav.map(([k,l,i])=>`<button data-action="nav" data-page="${k}" class="${ui.page===k?'active':''}" ${ui.page===k?'aria-current="page"':''}>${icon(i)}${l}${k==='clinic'&&active.length?`<span class="bubble">${active.length}</span>`:''}</button>`).join('')}</nav></div><div class="sidebar-foot"><strong>Pemantauan personel</strong>CPP Donggi dan CPP Matindok<br>Jumlah orang dan kesehatan harian</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Donggi Matindok <span aria-hidden="true">/</span> <b>${E(nav.find(n=>n[0]===ui.page)?.[1]||'Ringkasan')}</b></div><div class="top-controls"><label class="visually-hidden" for="global-site">CPP</label><select id="global-site">${siteOptions()}</select><span class="avatar">${E(init(actor()))}</span><label class="visually-hidden" for="role">Pengguna aktif</label><select id="role" aria-label="Pengguna aktif">${data.accounts.filter(a=>a.active).map(a=>`<option value="${a.id}" ${ui.accountId===a.id?'selected':''}>${E(a.name)} · ${PROFILES[a.role].label}</option>`).join('')}</select></div></header><div class="status-strip"><span>22 Oktober 2026 · WIB</span><span>${ui.site==='all'?'Kedua CPP':'CPP '+E(ui.site)}</span></div><main class="main" id="main">${content()}</main></div></div>`;
 document.title='POB Donggi Matindok · '+(nav.find(n=>n[0]===ui.page)?.[1]||'Ringkasan');
}
function content(){let body;if(['dcu','clinic'].includes(ui.page)&&!medical(ui.role))body='<div class="panel denied"><h2>Akses tim medis</h2><p class="muted mt">Angka kesehatan dan riwayat klinik tersedia pada tampilan petugas berwenang.</p></div>';else body=({overview,pob,dcu,clinic:()=>clinic()+lifecycle.requestsPanel(),reports,history:()=>daily.page(),settings,admin:()=>lifecycle.adminPage()}[ui.page]||overview)();return body+`<footer class="footer"><span>POB Donggi Matindok</span><span>v1.5</span></footer>`;}
function overview(){
 const snap=snapshot(data,ui.site),events=data.events.filter(inSite),alarms=data.cases.filter(c=>activeCase(c)&&inSite(c)),measures=activeMeasurements(data).filter(m=>day(m.time)===today).filter(inSite),ids=new Set(measures.map(m=>m.personId)),missing=data.people.filter(p=>p.site&&(ui.site==='all'||p.site===ui.site)&&!ids.has(p.id)),issues=events.filter(e=>e.result==='Perlu verifikasi'&&!e.voided);
 return head('','Ringkasan','',btn('Daftarkan tamu','guest')+btn(icon('scan')+' Coba pindai','scan','test-trigger'))+`<div class="stats">${stat('Orang di dalam kawasan',snap.inside,'')}${medical(ui.role)?stat('Belum diperiksa',missing.length,'','heart')+stat('Klinik menunggu',alarms.length,'','bell',true):stat('Internal',snap.categories[0].count,'')+stat('Mitra kerja',snap.categories[1].count,'')}${stat('Catatan perlu diperiksa',issues.length,'','report',issues.length>0)}</div><div class="overview-columns"><section class="panel"><div class="panel-head"><h2>Keberadaan per CPP</h2></div><div class="site-cards">${SITES.map(site=>`<button class="site-card site-button ${ui.site===site?'selected':''}" data-action="site-pob" data-site="${site}" aria-label="CPP ${site}, ${snapshot(data,site).inside} orang di dalam"><div class="site-title"><h3>CPP ${site}</h3><span class="connection-dot ${data.connections[site]?'online':'offline'}" title="${data.connections[site]?'Terhubung':'Koneksi terputus'}"></span></div><strong>${snapshot(data,site).inside}<small>orang</small></strong><div class="site-breakdown">${snapshot(data,site).categories.map(c=>`<span>${E(c.category||c.name)} <b>${c.count}</b></span>`).join('')}</div><span class="site-chevron" aria-hidden="true">›</span></button>`).join('')}</div><div class="split-heading mt"><h3>Keberadaan per area</h3>${btn('Semua area','overview-area','ghost','data-area="all"')}</div><div class="area-counts">${snap.areas.map(a=>`<button class="area-count" data-action="overview-area" data-area="${a.name}"><span>${a.name}</span><b>${a.count}</b><span aria-hidden="true">›</span></button>`).join('')}</div><button class="transit-row" data-action="overview-area" data-area="transit"><span>Di antara area</span><b>${snap.transit}</b><span aria-hidden="true">›</span></button></section><section class="panel"><div class="panel-head"><h2>${medical(ui.role)?'Antrean klinik':'Kegiatan terbaru'}</h2>${medical(ui.role)?btn('Semua kasus','clinic-filter','ghost','data-status="active"'):''}</div>${medical(ui.role)?(alarms.slice(0,5).map(caseRow).join('')||'<div class="empty">Tidak ada kasus menunggu.</div>'):`<div class="recent-list">${events.slice(0,5).map(e=>`<div class="recent-item">${person(e.personId)?nameCell(person(e.personId)):E(e.credential)}<p>${e.direction==='in'?'Masuk':'Keluar'} ${E(e.area==='SITE'?'gerbang kawasan':e.area)}<br>${when(e.time)}</p></div>`).join('')}</div>`}</section></div><section class="panel"><div class="panel-head"><h2>Masuk keluar terbaru</h2>${btn('Riwayat harian','nav','ghost','data-page="history"')}</div>${eventTable(events.slice(0,5))}</section>`;
}
function eventTable(events){return `<div class="table-wrap"><table><thead><tr><th>Waktu WIB</th><th>Nama</th><th>CPP / titik</th><th>Arah / metode</th><th>Hasil pencatatan</th></tr></thead><tbody>${events.map(e=>`<tr><td class="numeric">${when(e.time)}</td><td>${person(e.personId)?nameCell(person(e.personId)):E(e.credential||'Tidak dikenal')}</td><td>CPP ${E(e.site)}<br><span class="muted">${E(e.area==='SITE'?'Gerbang kawasan':e.area)}</span></td><td>${e.direction==='in'?'Masuk':'Keluar'}<br><span class="muted">${E(e.method)}</span></td><td>${pill(e.voided?'Dibatalkan':e.result,e.voided?'gray':e.result==='Berhasil'?'green':e.result==='Ditolak'?'red':'amber')}<div class="small muted trunc">${E(e.voided?.reason||e.message)}</div></td></tr>`).join('')||noData(5)}</tbody></table></div>`;}
function pob(){
 const snap=snapshot(data,ui.site);const q=ui.search.toLowerCase();const list=data.people.filter(p=>!p.archived&&(ui.site==='all'||p.site===ui.site||(!p.site&&p.home===ui.site))&&(ui.presence==='all'||(ui.presence==='inside'?!!p.site:!p.site))&&(ui.area==='all'||(ui.area==='transit'?p.site&&!p.area:p.area===ui.area))&&(ui.category==='all'||p.category===ui.category)&&(!q||[p.name,p.company,p.id,p.barcode].join(' ').toLowerCase().includes(q)));
 const max=Math.max(1,Math.ceil(list.length/12));ui.pageNo=Math.min(ui.pageNo,max);const rows=list.slice((ui.pageNo-1)*12,ui.pageNo*12);
 return head('KEBERADAAN PERSONEL','Keberadaan personel','Lihat siapa yang masih di dalam, sudah keluar, atau perlu diperiksa petugas.',btn(icon('plus')+' Daftarkan tamu','guest')+btn(icon('scan')+' Coba pindai kartu','scan','test-trigger'))+`<div class="stats">${stat('Tercatat di dalam',snap.inside,'Mengikuti CPP yang dipilih')}${stat('Internal',snap.categories[0].count,'Personel internal di dalam')}${stat('Mitra kerja',snap.categories[1].count,'Berbagai perusahaan')}${stat('Tamu',snap.categories[2].count,'Identitas sementara')}</div><div class="zones">${snap.areas.map(a=>`<button class="zone ${ui.area===a.name?'active':''}" data-action="area" data-area="${a.name}"><span>${a.name}</span><b>${a.count}</b></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>${ui.area==='all'?'Daftar personel':ui.area==='transit'?'Di antara area':E(ui.area)}</h2></div><div class="actions">${btn('Semua area','area','ghost','data-area="all"')}${btn('Di antara area ('+snap.transit+')','area','ghost','data-area="transit"')}</div></div><p class="filter-summary"> ${ui.site==='all'?'Kedua CPP':'CPP '+E(ui.site)} · ${ui.presence==='inside'?'Masih di dalam':ui.presence==='outside'?'Sudah di luar':'Semua status'} · ${ui.category==='all'?'Semua kategori':E(ui.category)} · ${ui.area==='all'?'Semua area':E(ui.area)}</p><div class="filters"><label class="visually-hidden" for="search">Cari personel</label><input id="search" class="input" placeholder="Cari nama, perusahaan, atau ID…" value="${E(ui.search)}"><select id="category" aria-label="Kategori"><option value="all">Semua kategori</option>${['Internal','Mitra kerja','Tamu'].map(c=>`<option ${ui.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="presence" aria-label="Status keberadaan"><option value="inside" ${ui.presence==='inside'?'selected':''}>Masih di dalam</option><option value="outside" ${ui.presence==='outside'?'selected':''}>Sudah di luar</option><option value="all" ${ui.presence==='all'?'selected':''}>Semua status</option></select></div><div class="table-wrap"><table><thead><tr><th>Identitas</th><th>Perusahaan</th><th>CPP / area terakhir</th><th>Waktu terakhir</th><th>Status</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${nameCell(p)}</td><td>${E(p.company)}</td><td>${p.site?'CPP '+p.site:'—'}<br><span class="muted">${E(p.area||(p.site?'Di antara area':'Di luar kawasan'))}</span></td><td class="numeric">${when(p.last)}</td><td>${pill(p.site?'Di dalam kawasan':'Di luar kawasan',p.site?'green':'gray')}${p.category==='Tamu'?`<div class="small muted">Berlaku ${E(p.expires)}</div>`:''}</td></tr>`).join('')||noData(5)}</tbody></table></div><div class="pagination"><span>${list.length} personel ditemukan · halaman ${ui.pageNo} dari ${max}</span><div class="actions">${btn('← Sebelumnya','paginate','',`data-delta="-1" ${ui.pageNo===1?'disabled':''}`)}${btn('Berikutnya →','paginate','',`data-delta="1" ${ui.pageNo===max?'disabled':''}`)}</div></div></section>`;
}
function evalPill(m){return pill({clear:'Tidak memerlukan tindak lanjut',incomplete:'Data belum lengkap',review:'Perlu pemeriksaan klinik',urgent:'Prioritas tinggi'}[m.evaluation.level],{clear:'green',incomplete:'gray',review:'amber',urgent:'red'}[m.evaluation.level]);}
function dcu(){
 const ms=activeMeasurements(data).filter(m=>day(m.time)===today).filter(inSite),ids=new Set(ms.map(x=>x.personId)),alerts=ms.filter(x=>['review','urgent'].includes(x.evaluation.level));const inside=data.people.filter(p=>p.site&&(ui.site==='all'||p.site===ui.site));const missing=inside.filter(p=>!ids.has(p.id));const q=ui.search.toLowerCase();const filtered=ms.filter(m=>(ui.dcuStatus==='all'||(ui.dcuStatus==='needs-review'?['review','urgent'].includes(m.evaluation.level):m.evaluation.level===ui.dcuStatus))&&(!q||[person(m.personId)?.name,m.personId].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(filtered.length/20));ui.dcuPage=Math.min(ui.dcuPage,pages);const rows=filtered.slice((ui.dcuPage-1)*20,ui.dcuPage*20);
 return head('PEMERIKSAAN KESEHATAN HARIAN (DCU)','Pemeriksaan sebelum bekerja','Hasil otomatis dan manual tercatat dalam riwayat setiap personel.',btn('Belum DCU ('+missing.length+')','missing')+btn(icon('plus')+' Catat pemeriksaan','measurement','primary'))+`<div class="stats">${stat('Sudah diperiksa',ids.size,'Jumlah orang yang diperiksa hari ini','check')}${stat('Belum DCU di dalam CPP',missing.length,'Orang di kawasan yang belum diperiksa','clock')}${stat('Hasil perlu tindak lanjut',alerts.length,'Hasil di luar batas pemeriksaan','bell',true)}${stat('Hasil belum lengkap',ms.filter(m=>m.evaluation.level==='incomplete').length,'Masih perlu dilengkapi petugas','heart')}</div><section class="panel"><div class="panel-head"><div><h2>Hasil pemeriksaan harian</h2><p>${filtered.length} hasil</p></div>${btn('Coba hasil alat','device-demo','test-trigger',`data-preset="normal"`)}</div><div class="filters"><input class="input" id="search" aria-label="Cari hasil DCU" placeholder="Cari nama atau ID personel…" value="${E(ui.search)}"><select id="dcu-status" aria-label="Status hasil"><option value="all">Semua hasil</option>${[['needs-review','Semua hasil perlu tindak lanjut'],['clear','Sesuai batas'],['review','Perlu ke klinik'],['urgent','Prioritas tinggi'],['incomplete','Belum lengkap']].map(([v,l])=>`<option value="${v}" ${ui.dcuStatus===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Identitas / CPP</th><th>Tekanan darah<br>mmHg</th><th>Oksigen (SpO₂)<br>%</th><th>Suhu<br>°C</th><th>Napas<br>/menit</th><th>Cara pencatatan / waktu</th><th>Status</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${nameCell(person(m.personId))}<div class="small muted">CPP ${m.site}</div></td><td class="numeric">${m.values.sys??'—'}/${m.values.dia??'—'}</td><td>${m.values.spo2??'—'}</td><td>${m.values.temp??'—'}</td><td>${m.values.rr??'—'}</td><td class="small">${E(m.source)}<br><span class="muted">${when(m.time)}</span></td><td>${evalPill(m)}<div class="small muted trunc">${E(m.evaluation.flags.join(' · '))}</div></td></tr>`).join('')||noData(7)}</tbody></table></div><div class="pagination"><span>Halaman ${ui.dcuPage} dari ${pages} · ${filtered.length} hasil pemeriksaan</span><div class="actions">${btn('← Sebelumnya','dcu-page','',`data-delta="-1" ${ui.dcuPage===1?'disabled':''}`)}${btn('Berikutnya →','dcu-page','',`data-delta="1" ${ui.dcuPage===pages?'disabled':''}`)}</div></div></section>`;
}
function caseRow(c){const p=person(c.personId),m=caseMeasure(c);return `<div class="case-row" data-case-id="${c.id}"><span class="spark"></span><div class="content"><button class="link" data-action="case" data-id="${c.id}">${E(p.name)}</button><p>${E(p.company)} · CPP ${c.site}</p><div class="small">${E(m.evaluation.flags.join(' · '))}</div><div class="small muted" style="margin-top:5px">${when(c.created)} WIB</div></div>${pill(({new:'Alarm baru',ongoing:'Ditangani',closed:'Selesai',void:'Dibatalkan',replaced:'Diganti hasil koreksi'}[c.status]||c.status),c.status==='new'?'red':c.status==='ongoing'?'amber':'green')}</div>`;}
function clinic(){const cases=data.cases.filter(inSite);const shown=cases.filter(c=>ui.clinicStatus==='all'||(ui.clinicStatus==='active'?activeCase(c):c.status===ui.clinicStatus));return head('','Klinik','',btn('Coba alarm','device-demo','test-trigger','data-preset="abnormal"'))+`<div class="stats">${stat('Alarm baru',cases.filter(c=>c.status==='new').length,'','bell',true)}${stat('Dalam pemeriksaan',cases.filter(c=>c.status==='ongoing').length,'','heart')}${stat('Kasus selesai',cases.filter(c=>c.status==='closed').length,'','check')}${stat('Total kasus',cases.length,'','report')}</div><section class="panel"><div class="panel-head"><h2>Daftar kasus</h2><div class="actions"><label class="check-row"><input id="sound" type="checkbox" ${data.settings.sound?'checked':''}>Bunyi alarm</label><select id="clinic-status" aria-label="Status kasus">${[['active','Kasus aktif'],['new','Alarm baru'],['ongoing','Dalam pemeriksaan'],['closed','Selesai'],['all','Semua kasus']].map(([v,l])=>`<option value="${v}" ${ui.clinicStatus===v?'selected':''}>${l}</option>`).join('')}</select></div></div>${shown.map(caseRow).join('')||'<div class="empty">Tidak ada kasus pada status ini.</div>'}</section>`;}

function reports(){return head('LAPORAN','Laporan dan riwayat perubahan','Unduh catatan masuk keluar, pemeriksaan, dan penanganan klinik sesuai periode yang dipilih.')+`<div class="filters"><label class="field">Dari tanggal WIB<input id="report-from" class="input" type="date" value="${ui.reportFrom}"></label><label class="field">Sampai tanggal WIB<input id="report-to" class="input" type="date" value="${ui.reportTo}"></label></div><div class="grid2 grid-equal"><div class="panel"><h2>Unduh laporan</h2><div class="form-grid mt">${[['events','Riwayat masuk keluar','Catatan berhasil, ditolak, dan yang perlu diperiksa petugas.'],['pob','Keberadaan saat ini','Daftar personel dan lokasi tercatat.'],...(medical(ui.role)?[['dcu','Hasil DCU','Nilai, sumber, waktu, dan penanda.'],['clinical','Tindakan klinik','Pemeriksaan dan keputusan dokter.']]:[]),['audit','Riwayat perubahan data','Akun, waktu, aktivitas, dan alasan.']].map(([k,t,d])=>`<div class="download-card"><h3>${t}</h3><p>${d}</p>${btn(icon('download')+' Ekspor CSV','csv','',`data-kind="${k}"`)}</div>`).join('')}</div></div><div class="panel"><h2>Perubahan data terbaru</h2><ol class="timeline">${data.audit.filter(a=>inReportRange(a.time)).slice(0,8).map(a=>`<li><strong>${E(a.action)}</strong><small>${when(a.time)} WIB · ${E(a.actor)}</small><p class="trunc">${E(auditDetail(a))}</p></li>`).join('')}</ol></div></div><section class="panel"><div class="panel-head"><h2>Masuk keluar terbaru</h2>${btn('Riwayat harian','nav','ghost','data-page="history"')}</div>${eventTable(data.events.filter(inSite).filter(e=>inReportRange(e.time)).slice(0,20))}</section>`;}
function settings(){const labels={sysHigh:'Tekanan darah atas tinggi ≥ mmHg',diaHigh:'Tekanan darah bawah tinggi ≥ mmHg',sysUrgent:'Tekanan darah atas prioritas tinggi > mmHg',diaUrgent:'Tekanan darah bawah prioritas tinggi > mmHg',sysLow:'Tekanan darah atas rendah ≤ mmHg',diaLow:'Tekanan darah bawah rendah ≤ mmHg',spo2Low:'Saturasi oksigen rendah < %',tempHigh:'Suhu tubuh tinggi ≥ °C',tempLow:'Suhu tubuh rendah ≤ °C',rrLow:'Frekuensi napas rendah < per menit',rrHigh:'Frekuensi napas tinggi > per menit'};return head('PENGATURAN SISTEM','Pengaturan dan penyimpanan data','Kelola batas alarm kesehatan, cadangan data, serta status koneksi lokasi.')+`<div class="grid2 grid-equal"><section class="panel"><h2>Koneksi lokasi</h2><p class="small muted mt">Catatan yang menunggu akan dikirim saat koneksi kembali tersedia.</p>${SITES.map(site=>`<div class="site-card mt"><div class="split-heading"><h3>CPP ${site}</h3>${pill(data.connections[site]?'Terhubung':'Terputus',data.connections[site]?'green':'red')}</div><p class="small muted mt">${(data.pending||[]).filter(q=>q.site===site).length} catatan menunggu pengiriman</p><div class="mt">${btn(data.connections[site]?'Coba putus koneksi':'Coba sambungkan kembali','connection','test-trigger',`data-site="${site}" ${ui.role!=='admin'?'disabled':''}`)}</div></div>`).join('')}</section><section class="panel"><h2>Cadangan dan pemulihan data</h2><p class="small muted mt">Unduh cadangan untuk menyimpan seluruh data. Pemulihan akan mengganti data yang sedang digunakan dengan isi berkas cadangan.</p><div class="actions mt">${btn('Unduh cadangan data','backup')}${lifecycle.restoreButton()}</div><div class="divider"></div><h3>Panduan penggunaan</h3><p class="small muted mt">Lihat langkah pencatatan masuk keluar, pemeriksaan, dan tindak lanjut klinik.</p><div class="actions mt">${btn('Buka panduan','guide')}${ui.role==='admin'?btn('Kembalikan data awal','reset','test-trigger'):''}</div></section></div>${clinician(ui.role)?`<section class="panel"><div class="panel-head"><div><h2>Batas alarm kesehatan</h2><p>Digunakan untuk menandai hasil yang memerlukan pemeriksaan lanjutan.</p></div></div><div class="notice">Batas pemeriksaan ditetapkan dokter sesuai pedoman dan metode pengukuran. Perubahan berlaku untuk hasil berikutnya; hasil sebelumnya menyimpan aturan saat pemeriksaan.</div><form id="rules-form"><div class="rule-grid">${Object.entries(labels).map(([k,l])=>`<div class="field"><label for="rule-${k}">${l}</label><input id="rule-${k}" class="input" name="${k}" type="number" required step="${k.includes('temp')?'.1':'1'}" value="${data.rules[k]}"></div>`).join('')}</div><div class="field mt"><label for="rule-reason">Alasan perubahan batas alarm</label><input id="rule-reason" class="input" name="reason" required placeholder="Tuliskan dasar dan alasan perubahan"></div><div class="form-actions"><button class="btn primary" type="submit">Simpan batas alarm</button></div></form></section>`:''}`;}
function optionsPeople(selected='DMF-0002'){return data.people.filter(p=>p.active).map(p=>`<option value="${E(p.id)}" ${p.id===selected?'selected':''}>${E(p.id)} · ${E(p.name)} · ${p.home}</option>`).join('');}
function modal(title,desc,html){document.querySelector('#modal-root').innerHTML=`<dialog id="dialog" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${desc}</p></div><button class="close" aria-label="Tutup" data-action="close">×</button></div><div class="modal-body">${html}</div></dialog>`;const d=document.querySelector('#dialog');d.showModal();d.addEventListener('click',e=>{if(e.target===d)d.close();});}
function close(){document.querySelector('#dialog')?.close();}
function formError(form,msg){let n=form.querySelector('.error');if(!n){n=document.createElement('p');n.className='error';n.setAttribute('role','alert');form.append(n);}n.textContent=msg;}
function scanModal(selected=null){modal('Uji pembaca kartu dan barcode','Pilih lokasi serta arah masuk atau keluar untuk mencoba pencatatan.',`<div class="notice">Coba <b>DMF-0201</b> atau <b>CARD-0201</b> untuk Raka Prasetyo yang awalnya di luar kawasan. Kartu dan barcode tersebut terhubung ke orang yang sama.</div><form id="scan-form"><div class="form-grid"><div class="field full"><label for="credential">ID / barcode / nomor kartu</label><input class="input code" id="credential" name="credential" value="DMF-0201" required autocomplete="off"></div><div class="field"><label for="scan-site">CPP</label><select id="scan-site" name="site">${siteOptions(false,ui.site==='all'?'Donggi':ui.site)}</select></div><div class="field"><label for="scan-area">Lokasi pembaca</label><select id="scan-area" name="area">${areaOptions()}</select></div><div class="field"><label for="direction">Arah perjalanan</label><select id="direction" name="direction"><option value="in">Masuk</option><option value="out">Keluar</option></select></div><div class="field"><label for="method">Metode</label><select id="method" name="method"><option>Kartu</option><option>Barcode dari kartu</option><option>Barcode dari HP</option></select></div></div><p class="small muted mt">Jika orang masih tercatat di area lain, petugas perlu memeriksa catatan sebelum mengubah lokasinya.</p><div class="form-actions"><button class="btn test-trigger" type="submit">${icon('scan')} Jalankan pemindaian <span class="test-badge">SIMULASI</span></button></div><div id="scan-result" aria-live="polite"></div></form>`);if(selected){document.querySelector('#credential').value=selected.credential||selected.barcode;document.querySelector('#scan-site').value=selected.site||selected.home;document.querySelector('#method').value=selected.method||'Barcode dari HP';}}
function measureModal(preset=null,selected=null){modal('Catat pemeriksaan DCU','Hasil dikaitkan dengan satu identitas dan sumber pemeriksaan.',`<p class="small muted" style="margin-bottom:18px">Pilih personel dan isi hasil pemeriksaan. Kosongkan nilai yang belum diukur.</p><div class="actions" style="margin-bottom:18px">${btn('Isi hasil tanpa alarm','fill-vitals','test-trigger','data-preset="normal"')}${btn('Isi suhu di atas batas','fill-vitals','test-trigger','data-preset="abnormal"')}${btn('Isi hasil prioritas tinggi','fill-vitals','test-trigger','data-preset="urgent"')}</div><form id="measure-form"><div class="form-grid"><div class="field full"><label for="patient">Identitas personel</label><select id="patient" name="personId">${optionsPeople()}</select></div><div class="field"><label for="measure-site">CPP pemeriksaan</label><select id="measure-site" name="site">${siteOptions(false,ui.site==='all'?'Donggi':ui.site)}</select></div><div class="field"><label for="source">Sumber hasil</label><select id="source" name="source"><option>Diisi petugas</option><option>Alat pemeriksaan DCU</option></select></div>${[['sys','Tekanan darah atas (sistolik) mmHg'],['dia','Tekanan darah bawah (diastolik) mmHg'],['spo2','Saturasi oksigen (SpO₂) %'],['temp','Suhu tubuh °C'],['rr','Frekuensi napas per menit']].map(([k,l])=>`<div class="field"><label for="v-${k}">${l}</label><input class="input" id="v-${k}" name="${k}" type="number" step="${k==='temp'?'.1':'1'}" placeholder="Kosongkan jika belum diukur"></div>`).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">Simpan hasil pemeriksaan</button></div></form>`);if(preset)fillVitals(preset);if(selected){document.querySelector('#patient').value=selected.id;document.querySelector('#measure-site').value=selected.site||selected.home;}}
function fillVitals(preset){const v=preset==='urgent'?{sys:185,dia:122,spo2:98,temp:36.7,rr:18}:preset==='abnormal'?{sys:118,dia:76,spo2:98,temp:38.2,rr:18}:{sys:118,dia:76,spo2:98,temp:36.6,rr:16};for(const [k,x]of Object.entries(v))document.querySelector('#v-'+k).value=x;document.querySelector('#source').value='Alat pemeriksaan DCU';}
function legacyPersonModal(id){const p=person(id);if(!p)return;const es=data.events.filter(e=>e.personId===id).slice(0,15),ms=data.measurements.filter(m=>m.personId===id).slice(0,10),cs=data.cases.filter(c=>c.personId===id);modal(E(p.name),E(p.id)+' · '+E(p.category)+' · '+E(p.company),`<div class="split-heading"><div>${pill(p.site?'Di dalam CPP '+p.site:'Di luar kawasan',p.site?'green':'gray')}<p class="small muted mt">${E(p.area||(p.site?'Di antara area':'Belum ada area aktif'))}</p></div>${['admin','security'].includes(ui.role)?btn('Koreksi lokasi','reconcile','',`data-id="${p.id}"`):''}</div><div class="divider"></div><h3>Riwayat masuk keluar</h3><ol class="timeline">${es.map(e=>`<li><strong>${e.direction==='in'?'Masuk':'Keluar'} · ${E(e.area==='SITE'?'Gerbang kawasan':e.area)}</strong><small>${when(e.time)} WIB · CPP ${e.site} · ${E(e.method)}</small><p>${E(e.result)} · ${E(e.message)}</p></li>`).join('')||'<li>Belum ada catatan akses.</li>'}</ol>${medical(ui.role)?`<div class="divider"></div><h3>Riwayat pemeriksaan dan klinik</h3><ol class="timeline">${ms.map(m=>`<li><strong>${when(m.time)} WIB · ${E(m.source)}</strong><p>Tekanan darah ${m.values.sys??'—'}/${m.values.dia??'—'} · SpO₂ ${m.values.spo2??'—'}% · suhu ${m.values.temp??'—'}°C · RR ${m.values.rr??'—'}</p>${evalPill(m)}${m.corrections.length?'<p>Memiliki koreksi dengan riwayat.</p>':''}${clinician(ui.role)?`<div style="margin-top:7px">${btn('Koreksi hasil','correct-measure','',`data-id="${m.id}"`)}</div>`:''}</li>`).join('')||'<li>Belum ada hasil DCU.</li>'}</ol>${cs.map(c=>caseRow(c)).join('')}`:''}`);}
function legacyCaseModal(id){if(!medical(ui.role))return;const c=data.cases.find(x=>x.id===id);if(!c)return;const p=person(c.personId),m=caseMeasure(c);modal('Kasus '+E(c.id),E(p.name)+' · '+E(p.company)+' · CPP '+c.site,`<div class="split-heading">${pill(c.status==='new'?'Alarm baru':c.status==='ongoing'?'Dalam pemeriksaan':'Keputusan tercatat',c.status==='new'?'red':c.status==='ongoing'?'amber':'green')}${c.status==='new'?btn('Terima kasus','ack','primary',`data-id="${c.id}"`):''}</div><div class="vitals">${[['Tekanan darah mmHg',`${m.values.sys}/${m.values.dia}`],['Oksigen (SpO₂)',m.values.spo2+'%'],['Suhu',m.values.temp+'°C'],['Napas /menit',m.values.rr]].map(([l,v])=>`<div class="vital"><span>${l}</span><b>${E(v)}</b></div>`).join('')}</div><div class="notice alert"><div><b>${E(m.evaluation.flags.join(' · '))}</b><p>Aturan pemeriksaan · ${when(m.time)} WIB · ${E(m.source)}</p></div></div><h3>Riwayat penanganan</h3><ol class="timeline"><li><strong>Hasil pemeriksaan memerlukan tindak lanjut</strong><small>${when(c.created)} WIB · ${E(m.actor)}</small><p>Hasil awal tetap disimpan.</p></li>${c.ack?`<li><strong>Kasus diterima</strong><small>${when(c.ack.time)} WIB · ${E(c.ack.actor)}</small></li>`:''}${c.actions.map(a=>`<li>${a.voided?pill('Dibatalkan','gray'):a.replacedBy?pill('Diganti','gray'):''}<strong>${E({observe:'Observasi dilanjutkan',allowed:'Diizinkan bekerja oleh dokter',held:'Belum diizinkan bekerja oleh dokter'}[a.decision])}</strong><small>${when(a.time)} WIB · ${E(a.actor)}</small><p>${E(a.note)}</p>${a.recheck?`<p>Pemeriksaan ulang: ${E(a.recheck)}</p>`:''}</li>`).join('')}</ol>${c.status!=='new'&&clinician(ui.role)?`<div class="divider"></div><h3>Tambah catatan dokter</h3><form id="action-form" data-id="${c.id}"><div class="field mt"><label for="recheck">Hasil pemeriksaan ulang jika ada</label><input class="input" id="recheck" name="recheck" placeholder="Contoh: hasil ulang dicatat dokter"></div><div class="field mt"><label for="note">Pemeriksaan dan tindakan</label><textarea id="note" name="note" required placeholder="Catat pemeriksaan, tindakan, atau arahan dokter…"></textarea></div><div class="field mt"><label for="decision">Keputusan dokter</label><select name="decision" id="decision"><option value="observe">Masih dalam pemeriksaan / observasi</option><option value="allowed">Diizinkan bekerja oleh dokter</option><option value="held">Belum diizinkan bekerja oleh dokter</option></select></div><div class="form-actions"><button class="btn primary" type="submit">Simpan tindakan dan keputusan</button></div></form>`:c.status==='new'?'<p class="small muted">Terima kasus untuk memulai tindak lanjut.</p>':'<p class="small muted">Keputusan dokter ditambahkan melalui peran Dokter atau Administrator.</p>'}`);}
function personModal(id){lifecycle.person(id);}
function correctionModal(id){lifecycle.correction(id);}
function caseModal(id){legacyCaseModal(id);lifecycle.decorateCase(id);}
function guestModal(){modal('Daftarkan tamu','Satu identitas sementara untuk kartu atau barcode.',`<form id="guest-form"><div class="form-grid"><div class="field"><label for="guest-name">Nama tamu</label><input id="guest-name" class="input" name="name" required maxlength="80"></div><div class="field"><label for="guest-company">Perusahaan</label><input id="guest-company" class="input" name="company" required maxlength="80"></div><div class="field"><label for="guest-site">CPP tujuan</label><select id="guest-site" name="home">${siteOptions(false,ui.site==='all'?'Donggi':ui.site)}</select></div><div class="field"><label for="expires">Berlaku sampai</label><input id="expires" class="input" name="expires" type="date" value="${today}" min="${today}" required></div></div><div class="form-actions"><button type="submit" class="btn primary">Buat identitas tamu</button></div></form>`);}
function reconcileModal(id){const p=person(id);modal('Koreksi lokasi tercatat','Catatan pemindaian asli tetap disimpan. Alasan dan akun koreksi dicatat.',`<form id="reconcile-form" data-id="${id}"><div class="notice">${E(p.name)} · saat ini ${E(p.site||'di luar kawasan')} / ${E(p.area||'tanpa area aktif')}</div><div class="form-grid"><div class="field"><label for="correct-site">Lokasi yang sudah diverifikasi</label><select id="correct-site" name="site"><option value="">Di luar kawasan</option>${siteOptions(false,p.site)}</select></div><div class="field"><label for="correct-area">Area setelah verifikasi</label><select id="correct-area" name="area">${areaOptions(false,p.area)}</select></div><div class="field full"><label for="reason">Alasan koreksi</label><textarea id="reason" name="reason" required placeholder="Sebutkan hasil verifikasi dan alasan perubahan…"></textarea></div></div><div class="form-actions"><button class="btn primary" type="submit">Simpan koreksi</button></div></form>`);}
function legacyCorrectionModal(id){const m=data.measurements.find(x=>x.id===id);modal('Koreksi hasil DCU','Nilai asli dan alasan perubahan dipertahankan.',`<form id="correction-form" data-id="${id}"><div class="form-grid">${[['sys','Sistolik'],['dia','Diastolik'],['spo2','SpO₂'],['temp','Suhu tubuh'],['rr','RR']].map(([k,l])=>`<div class="field"><label for="corr-${k}">${l}</label><input id="corr-${k}" class="input" name="${k}" type="number" step="${k==='temp'?'.1':'1'}" value="${m.values[k]??''}"></div>`).join('')}<div class="field full"><label for="correction-reason">Alasan koreksi</label><textarea id="correction-reason" name="reason" required></textarea></div></div><div class="form-actions"><button class="btn primary" type="submit">Simpan sebagai koreksi dengan riwayat</button></div></form>`);}
function sound(){if(!data.settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=740;g.gain.value=.08;o.start();o.stop(ctx.currentTime+.25);o.onended=()=>ctx.close();}catch{}}
function guide(){modal('Panduan penggunaan','Pencatatan personel dan pemeriksaan kesehatan harian.',`<ol class="timeline">${[['Daftarkan personel','Administrator menambahkan identitas, perusahaan, penugasan, serta kartu atau barcode pada menu Administrasi.'],['Catat masuk keluar','Pindai kartu atau barcode pada pembaca masuk dan keluar. Daftar keberadaan menunjukkan orang yang belum tercatat keluar.'],['Lakukan pemeriksaan harian','Petugas memilih personel, mencatat hasil pemeriksaan, dan memeriksa kelengkapan nilainya.'],['Tindak lanjuti di klinik','Hasil yang melewati batas pemeriksaan masuk ke klinik. Petugas menerima pemberitahuan, kemudian dokter mencatat tindakan dan keputusan.'],['Lihat riwayat','Buka Riwayat harian untuk seluruh kegiatan pada satu tanggal. Klik nama untuk riwayat per orang dan pilihan rentang tanggal.'],['Perbaiki catatan yang salah','Catatan masuk keluar dibatalkan dengan alasan dan verifikasi lokasi. Perubahan hasil medis diajukan petugas medis dan disetujui dokter.']].map(([t,d])=>`<li><strong>${t}</strong><p>${d}</p></li>`).join('')}</ol>`);}
function download(filename,body,type='text/csv;charset=utf-8'){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(kind){if(['dcu','clinical'].includes(kind)&&!medical(ui.role))return;let rows;
 if(kind==='events')rows=[['Waktu WIB','ID','Nama','CPP','Area','Arah','Metode','Hasil','Catatan'],...data.events.filter(inSite).filter(e=>inReportRange(e.time)).map(e=>[when(e.time),e.personId,person(e.personId)?.name,e.site,e.area,e.direction,e.method,e.voided?'Dibatalkan':e.result,e.voided?e.voided.reason:e.message])];
 if(kind==='pob')rows=[['ID','Nama','Kategori','Perusahaan','CPP tercatat','Area tercatat','Waktu terakhir WIB'],...data.people.filter(p=>ui.site==='all'||p.site===ui.site||(!p.site&&p.home===ui.site)).map(p=>[p.id,p.name,p.category,p.company,p.site,p.area,when(p.last)])];
 if(kind==='dcu')rows=[['ID pemeriksaan','ID personel','Nama','CPP','Waktu WIB','Sistolik','Diastolik','SpO2','Suhu','RR','Sumber','Petugas','Profil','Penanda'],...activeMeasurements(data).filter(m=>inReportRange(m.time)).filter(inSite).map(m=>[m.id,m.personId,person(m.personId)?.name,m.site,when(m.time),m.values.sys,m.values.dia,m.values.spo2,m.values.temp,m.values.rr,m.source,m.actor,m.rulesLabel,m.evaluation.flags.join('; ')])];
 if(kind==='clinical')rows=[['Kasus','ID','Nama','CPP','Waktu tindakan WIB','Dokter','Pemeriksaan ulang','Tindakan','Keputusan'],...data.cases.filter(inSite).flatMap(c=>c.actions.filter(a=>inReportRange(a.time)&&!a.voided&&!a.replacedBy).map(a=>[c.id,c.personId,person(c.personId)?.name,c.site,when(a.time),a.actor,a.recheck,a.note,({observe:'Masih dalam pemeriksaan',allowed:'Diizinkan bekerja',held:'Belum diizinkan bekerja'}[a.decision])]))];
 if(kind==='audit')rows=[['Waktu WIB','Akun','Aktivitas','Detail'],...data.audit.filter(a=>inReportRange(a.time)).map(a=>[when(a.time),a.actor,a.action,auditDetail(a)])];
 const cell=v=>{let t=String(v??'');if(/^[=+\-@]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};download('POB-'+kind+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'));toast('Laporan CSV berhasil diunduh.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
 if(a==='dcu-page'){ui.dcuPage+=Number(b.dataset.delta);render();} if(a==='clinic-filter'&&medical(ui.role)){ui.page='clinic';ui.clinicStatus=b.dataset.status;render();}
 if(a==='review-access'){const list=data.events.filter(inSite).filter(e=>e.result==='Perlu verifikasi'&&!e.voided);modal('Catatan perlu diperiksa',`${list.length} catatan`,eventTable(list));}
if(a==='summary'){ui.dcuPage=1;
 const l=b.dataset.label;ui.search='';ui.pageNo=1;if(l==='Catatan perlu diperiksa'){document.dispatchEvent(new CustomEvent('pob-review'));return;}
 if(['Tercatat di dalam','Internal','Mitra kerja','Tamu','Orang di dalam kawasan','Personel terdaftar'].includes(l)){ui.page='pob';ui.area='all';ui.presence=l==='Personel terdaftar'?'all':'inside';ui.category=['Internal','Mitra kerja','Tamu'].includes(l)?l:'all';if(l==='Personel terdaftar')ui.site='all';render();}
 else if(['Belum diperiksa','Sudah DCU hari ini','Sudah diperiksa','Hasil perlu tindak lanjut','Hasil belum lengkap','Belum DCU di dalam CPP'].includes(l)&&medical(ui.role)){ui.page='dcu';ui.dcuStatus=l==='Hasil perlu tindak lanjut'?'needs-review':l==='Hasil belum lengkap'?'incomplete':'all';render();if(['Belum diperiksa','Belum DCU di dalam CPP'].includes(l))document.querySelector('[data-action="missing"]').click();}
 else if(medical(ui.role)){ui.page='clinic';ui.clinicStatus=({'Alarm baru':'new','Dalam pemeriksaan':'ongoing','Kasus selesai':'closed','Total kasus':'all'})[l]||'active';render();}
 else toast('Tindak lanjut dikelola oleh tim medis.');
 }
 if(a==='overview-area'){ui.page='pob';ui.area=b.dataset.area;ui.presence='inside';ui.category='all';ui.search='';ui.pageNo=1;render();}
 if(a==='mobile-menu'){ui.menuOpen=!ui.menuOpen;render();}if(a==='nav'){ui.menuOpen=false;ui.page=b.dataset.page;ui.search='';ui.pageNo=1;render();}
 if(a==='close')close();if(a==='scan')scanModal();if(a==='measurement')measureModal();if(a==='device-demo')measureModal(b.dataset.preset);if(a==='fill-vitals')fillVitals(b.dataset.preset);if(a==='person')personModal(b.dataset.id);if(a==='case')caseModal(b.dataset.id);if(a==='guest')guestModal();if(a==='guide')guide();if(a==='reconcile')reconcileModal(b.dataset.id);if(a==='correct-measure'&&clinician(ui.role))correctionModal(b.dataset.id);
 if(a==='area'){ui.area=b.dataset.area;ui.presence='inside';ui.category='all';ui.search='';ui.pageNo=1;render();}if(a==='site-pob'){ui.site=b.dataset.site;ui.page='pob';ui.area='all';ui.category='all';ui.presence='inside';ui.pageNo=1;ui.search='';render();}if(a==='paginate'){ui.pageNo+=Number(b.dataset.delta);render();}
 if(a==='ack'){acknowledge(data,b.dataset.id,actor());save();render();caseModal(b.dataset.id);toast('Kasus diterima. Akun dan waktu dicatat.');}
 if(a==='csv')csv(b.dataset.kind);if(a==='backup'){download('Cadangan-POB.json',JSON.stringify(data,null,2),'application/json');toast('Cadangan data berhasil diunduh.');}
 if(a==='reset'&&ui.role==='admin'){modal('Kembalikan data awal','Perubahan pada browser ini akan diganti dengan kondisi awal.',`<p class="small muted">Unduh cadangan JSON terlebih dahulu bila ingin mempertahankan perubahan yang sudah dibuat.</p><div class="form-actions">${btn('Batal','close')}${btn('Ya, kembalikan data awal','confirm-reset','red')}</div>`);}
 if(a==='confirm-reset'&&ui.role==='admin'){data=makeSeed();save();close();render();toast('Data dikembalikan ke kondisi awal.');}
 if(a==='connection'&&ui.role==='admin'){const site=b.dataset.site;if(data.connections[site]){data.connections[site]=false;audit(data,actor(),'Koneksi lokasi diputus',site);}else{const n=syncSite(data,site,actor());toast(n+' catatan antrean diproses.');}save();render();}
 if(a==='missing'){const ids=new Set(activeMeasurements(data).filter(m=>day(m.time)===today).filter(inSite).map(m=>m.personId));const ps=data.people.filter(p=>p.site&&(ui.site==='all'||p.site===ui.site)&&!ids.has(p.id));modal('Personel belum DCU','Orang yang masih berada di kawasan dan belum memiliki hasil pemeriksaan hari ini.',`<p class="small muted">${ps.length} orang belum memiliki hasil pemeriksaan hari ini.</p><div class="table-wrap"><table><thead><tr><th>Identitas</th><th>Perusahaan</th><th>CPP</th><th>Pemeriksaan</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${nameCell(p)}</td><td>${E(p.company)}</td><td>${p.site}</td><td>${btn('Catat DCU','person-measurement','',`data-id="${p.id}"`)}</td></tr>`).join('')||noData(4)}</tbody></table></div>`);}
 }catch(err){toast(err.message,true);}});
document.addEventListener('click',e=>{if(e.target.closest('button,input,select,a'))return;const row=e.target.closest('[data-case-id]');if(row&&medical(ui.role))caseModal(row.dataset.caseId);});
document.addEventListener('pob-review',()=>{const list=data.events.filter(inSite).filter(e=>e.result==='Perlu verifikasi'&&!e.voided);modal('Catatan perlu diperiksa',`${list.length} catatan`,eventTable(list));});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='global-site'){ui.site=t.value;ui.pageNo=1;ui.dcuPage=1;render();}if(t.id==='role'){ui.accountId=t.value;ui.role=data.accounts.find(a=>a.id===t.value).role;if((['dcu','clinic'].includes(ui.page)&&!medical(ui.role))||(ui.page==='admin'&&ui.role!=='admin'))ui.page='overview';close();render();}if(t.id==='category'||t.id==='presence'){ui[t.id]=t.value;ui.pageNo=1;render();}if(t.id==='dcu-status'){ui.dcuStatus=t.value;ui.dcuPage=1;render();}if(t.id==='clinic-status'){ui.clinicStatus=t.value;render();}if(t.id==='report-from'||t.id==='report-to'){const key=t.id==='report-from'?'reportFrom':'reportTo';const old=ui[key];ui[key]=t.value;if(ui.reportFrom&&ui.reportTo&&ui.reportFrom>ui.reportTo){ui[key]=old;toast('Tanggal awal tidak boleh melewati tanggal akhir.',true);}render();}if(t.id==='sound'){data.settings.sound=t.checked;save();if(t.checked)sound();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;ui.search=e.target.value;ui.pageNo=1;ui.dcuPage=1;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id.startsWith('lc-'))return;const d=Object.fromEntries(new FormData(f));try{
 if(f.id==='scan-form'){const ev=scan(data,d,actor());save();document.querySelector('#scan-result').innerHTML=`<div class="notice ${ev.result==='Berhasil'?'':'warning'} mt"><b>${E(ev.result)} · ${E(ev.gate)}</b><p>${E(ev.message)}</p><p>${E(person(ev.personId)?.name||ev.credential)} · ${when(ev.time)} WIB</p></div>`;document.querySelector('#main').innerHTML=content();toast(ev.message,ev.result==='Ditolak');}
 if(f.id==='measure-form'){if(!medical(ui.role))throw Error('Akses tim medis diperlukan.');const values=Object.fromEntries(['sys','dia','spo2','temp','rr'].map(k=>[k,d[k].trim()===''?null:Number(d[k])]));const m=addMeasurement(data,{personId:d.personId,site:d.site,source:d.source,values},actor());save();close();ui.page='dcu';ui.search='';render();if(['review','urgent'].includes(m.evaluation.level)){sound();toast('Hasil tersimpan. Pemberitahuan terkirim ke klinik.');}else toast(m.evaluation.level==='incomplete'?'Hasil belum lengkap tersimpan; tidak dianggap selesai.':'Hasil pemeriksaan tersimpan dan tidak memerlukan tindak lanjut.');}
 if(f.id==='action-form'){if(!clinician(ui.role))throw Error('Keputusan melalui peran dokter.');addAction(data,f.dataset.id,d,actor());save();render();caseModal(f.dataset.id);toast('Tindakan dan keputusan dokter tersimpan.');}
 if(f.id==='reconcile-form'){if(!['admin','security'].includes(ui.role))throw Error('Akses petugas POB diperlukan.');reconcile(data,f.dataset.id,d,actor());save();render();personModal(f.dataset.id);toast('Koreksi lokasi disimpan dengan alasan dan akun.');}
 if(f.id==='guest-form'){if(!d.name.trim()||!d.company.trim()||d.expires<today)throw Error('Lengkapi identitas dan masa berlaku tamu.');const id='GUEST-'+String(data.people.length+1).padStart(4,'0');data.people.push({id,name:d.name.trim(),company:d.company.trim(),category:'Tamu',home:d.home,card:'CARD-'+id,barcode:id,active:true,expires:d.expires,site:null,area:null,last:stamp(data)});audit(data,actor(),'Tamu didaftarkan',id+' · berlaku sampai '+d.expires);save();render();credentials.show(id);}
 if(f.id==='rules-form'){if(!clinician(ui.role))throw Error('Akses dokter diperlukan.');const next={...data.rules};for(const k of Object.keys(next)){next[k]=Number(d[k]);if(!Number.isFinite(next[k])||next[k]<=0)throw Error('Semua batas harus berupa angka positif.');}if(next.tempLow>=next.tempHigh||next.rrLow>=next.rrHigh||next.sysLow>=next.sysHigh||next.diaLow>=next.diaHigh||next.sysHigh>=next.sysUrgent||next.diaHigh>=next.diaUrgent)throw Error('Urutan batas rendah, tinggi, dan prioritas tidak valid.');if(!d.reason.trim())throw Error('Isi alasan perubahan.');const before={...data.rules};data.rules=next;audit(data,actor(),'Batas alarm kesehatan klinik diubah',JSON.stringify({before,after:next,reason:d.reason.trim()}));save();render();toast('Aturan pemeriksaan disimpan untuk pemeriksaan berikutnya; hasil lama tidak dihitung ulang.');}
 if(f.id==='correction-form'){if(!clinician(ui.role))throw Error('Akses dokter diperlukan.');if(!d.reason.trim())throw Error('Alasan koreksi wajib diisi.');const old=data.measurements.find(m=>m.id===f.dataset.id);const values=Object.fromEntries(['sys','dia','spo2','temp','rr'].map(k=>[k,d[k].trim()===''?null:Number(d[k])]));const corrected=addMeasurement(data,{personId:old.personId,site:old.site,source:'Koreksi manual dari '+old.id,values},actor());corrected.corrects=old.id;old.corrections.push({measurementId:corrected.id,reason:d.reason.trim(),actor:actor(),time:corrected.time});audit(data,actor(),'Koreksi hasil DCU',old.id+' → '+corrected.id+' · '+d.reason.trim());save();render();personModal(old.personId);toast('Hasil koreksi tersimpan; hasil asli tetap ada.');}
 }catch(err){formError(f,err.message);}});
const daily=createDailyHistory({data:()=>data,ui,E,when,head,stat,btn,pill,nameCell,download,render});
const credentials=createCredentialUI({data:()=>data,ui,E,when,pill,btn,modal,toast,download,actor,save,render,scan:scanModal,measure:p=>measureModal(null,p)});
const lifecycle=createLifecycleUI({data:()=>data,replaceData:x=>{data=x;},ui,E,when,pill,btn,modal,close,toast,download,head,stat,nameCell,actor,save,render,credentials});
render();save();
